constraints={2:9,12:2,15:4,17:9,18:7,20:6,21:6}
valid=[]
for p in range(1,23):
    m={}
    ok=True
    for r,v in constraints.items():
        k=r%p
        if k in m and m[k]!=v: ok=False; break
        m[k]=v
    if ok: valid.append((p,m))
print(valid[:5])
p,m=valid[0]
# For any residues without a nonzero stripe seed, they should be background 0.
row=[m.get(i%p,0) for i in range(22)]
print('period',p,'sequence',row)
print([[v]*22 for v in row])
